UNIT_MULTIPLIERS = {
    "weeks": 604800,
    "days": 86400,
    "hours": 3600,
    "minutes": 60,
    "seconds": 1,
}


def add(a: int, b: int) -> int:
    """Return the sum of two durations in seconds."""
    return a + b


def convert(seconds: int, to_unit: str) -> float:
    """Convert seconds into the named unit; raise ValueError on unknown unit."""
    if to_unit not in UNIT_MULTIPLIERS:
        raise ValueError(f"Unknown unit: {to_unit!r}")
    return seconds / UNIT_MULTIPLIERS[to_unit]

def human(seconds: int) -> str:
    """Render a non-negative integer of seconds as a human-readable duration string.

    Uses unit multipliers w/d/h/m/s in largest-first order. Zero-valued units are
    omitted entirely. Segments are separated by a single space.
    """
    if seconds < 0:
        raise ValueError("seconds must be non-negative")

    if seconds == 0:
        return "0s"

    units = [(604800, "w"), (86400, "d"), (3600, "h"), (60, "m"), (1, "s")]
    parts = []

    for multiplier, unit in units:
        count = seconds // multiplier
        if count > 0:
            parts.append(f"{count}{unit}")
        seconds %= multiplier

    return " ".join(parts)

import pytest

from duration.parser import parse_duration


@pytest.mark.parametrize(
    ("input_str", "expected"),
    [
        ("1w", 604800),
        ("2d", 172800),
        ("3h", 10800),
        ("4m", 240),
        ("5s", 5),
    ],
)
def test_each_unit_alone(input_str: str, expected: int) -> None:
    assert parse_duration(input_str) == expected


@pytest.mark.parametrize(
    ("input_str", "expected"),
    [
        ("1h30m", 5400),
        ("2d4h", 187200),
        ("1w2d3h4m5s", 788645),
    ],
)
def test_multi_unit(input_str: str, expected: int) -> None:
    assert parse_duration(input_str) == expected


@pytest.mark.parametrize(
    ("input_str", "expected"),
    [
        ("30m1h", 5400),
        ("5s4m3h2d1w", 788645),
        ("1s2m3h4d5w", 3380521),
    ],
)
def test_any_order(input_str: str, expected: int) -> None:
    assert parse_duration(input_str) == expected


@pytest.mark.parametrize(
    ("input_str", "expected"),
    [
        ("90", 90),
        ("42", 42),
        ("1000", 1000),
    ],
)
def test_bare_number(input_str: str, expected: int) -> None:
    assert parse_duration(input_str) == expected


def test_empty_string() -> None:
    with pytest.raises(ValueError):
        parse_duration("")


def test_invalid_unit_x() -> None:
    with pytest.raises(ValueError):
        parse_duration("1x")


def test_invalid_unit_z() -> None:
    with pytest.raises(ValueError):
        parse_duration("5z")


def test_non_numeric_abc() -> None:
    with pytest.raises(ValueError):
        parse_duration("abc")


def test_float_not_allowed() -> None:
    with pytest.raises(ValueError):
        parse_duration("1.5h")


def test_negative_number_h() -> None:
    with pytest.raises(ValueError):
        parse_duration("-1h")


def test_double_negative() -> None:
    with pytest.raises(ValueError):
        parse_duration("--5")


def test_mixed_valid_invalid_1h2x3m() -> None:
    with pytest.raises(ValueError):
        parse_duration("1h2x3m")


def test_spaces_not_allowed() -> None:
    with pytest.raises(ValueError):
        parse_duration("1h 2m")


def test_trailing_unit_no_number_h() -> None:
    with pytest.raises(ValueError):
        parse_duration("h")

import pytest
from duration.arithmetic import add, convert

@pytest.mark.parametrize(
    "a,b,expected",
    [
        (1, 2, 3),
        (0, 5, 5),
        (86400, 3600, 90000),
        (604800, 86400, 691200),
        (31536000, 31536000, 63072000),
    ],
)
def test_add(a: int, b: int, expected: int) -> None:
    assert add(a, b) == expected

@pytest.mark.parametrize(
    "seconds,unit,expected",
    [
        (3600, "hours", 1.0),
        (86400, "days", 1.0),
        (604800, "weeks", 1.0),
        (3600, "seconds", 3600.0),
    ],
)
def test_convert_whole(seconds: int, unit: str, expected: float) -> None:
    assert convert(seconds, unit) == expected

@pytest.mark.parametrize(
    "seconds,unit,expected",
    [
        (90, "minutes", 1.5),
        (3661, "hours", 1.016944444),
    ],
)
def test_convert_fractional(seconds: int, unit: str, expected: float) -> None:
    assert abs(convert(seconds, unit) - expected) < 1e-5

def test_convert_zero() -> None:
    assert convert(0, "hours") == 0.0

def test_convert_returns_float_not_string() -> None:
    assert isinstance(convert(3600, "hours"), float)

def test_convert_invalid_unit_raises_value_error() -> None:
    with pytest.raises(ValueError):
        convert(3600, "invalid")

import pytest

from duration.formatting import human as human_duration


def test_zero_seconds() -> None:
    assert human_duration(0) == "0s"


@pytest.mark.parametrize(
    "seconds,expected",
    [
        (1, "1s"),
        (60, "1m"),
        (3600, "1h"),
        (86400, "1d"),
        (604800, "1w"),
    ],
)
def test_single_unit(seconds: int, expected: str) -> None:
    assert human_duration(seconds) == expected


@pytest.mark.parametrize(
    "seconds,expected",
    [
        (2, "2s"),
        (604801, "1w 1s"),
    ],
)
def test_single_unit_plural(seconds: int, expected: str) -> None:
    assert human_duration(seconds) == expected


@pytest.mark.parametrize(
    "seconds,expected",
    [
        (604800 + 172800 + 3600 + 120 + 5, "1w 2d 1h 2m 5s"),
        (3600 + 90, "1h 1m 30s"),
    ],
)
def test_multi_unit(seconds: int, expected: str) -> None:
    assert human_duration(seconds) == expected


@pytest.mark.parametrize(
    "seconds,expected",
    [
        (604800 + 3600, "1w 1h"),
        (86400 + 5, "1d 5s"),
    ],
)
def test_omit_zero_units(seconds: int, expected: str) -> None:
    assert human_duration(seconds) == expected


@pytest.mark.parametrize(
    "seconds,expected",
    [
        (604800 * 3 + 1, "3w 1s"),
    ],
)
def test_large_values(seconds: int, expected: str) -> None:
    assert human_duration(seconds) == expected


@pytest.mark.parametrize(
    "seconds,expected",
    [
        (604800, "1w"),
        (86400, "1d"),
    ],
)
def test_exact_unit_boundaries(seconds: int, expected: str) -> None:
    assert human_duration(seconds) == expected


@pytest.mark.parametrize(
    "seconds,expected",
    [
        (604800 + 5, "1w 5s"),
    ],
)
def test_mixed_with_gaps(seconds: int, expected: str) -> None:
    assert human_duration(seconds) == expected


@pytest.mark.parametrize(
    "seconds",
    [0, 1, 60, 3600, 86400, 604800, 604801, 3600 + 90],
)
def test_no_leading_trailing_spaces(seconds: int) -> None:
    result = human_duration(seconds)
    assert not result.startswith(" ")
    assert not result.endswith(" ")


@pytest.mark.parametrize(
    "seconds",
    [604801, 3600 + 90],
)
def test_single_space_between_segments(seconds: int) -> None:
    result = human_duration(seconds)
    assert "  " not in result
